"""Minimal methods-only edit in isolated manuscript v3, with backup and audit."""
import difflib,hashlib,json,sys
from pathlib import Path
BASE=Path(__file__).resolve().parents[1];sys.path.insert(0,str(BASE));import audit
REV=BASE/'manuscript_revision_v3_compat49'
P=REV/'source/sections/03_method.tex'
OLD='The supplementary EvoSuite configuration (E1) enables assertions with MUTATION strategy, scaffolding and runtime dependency while retaining BRANCH, the 60-second search budget, disabled test archive and disabled separate classloader. Seeds are 20261023 plus the original sampling-manifest 1-based index. All 49 historical keys are scheduled serially; failures remain in the cohort. A generation attempt has a 240-second cap, with at most one conditional sanitized-classpath retry inherited from the adapter; Maven commands have a 300-second cap. Native ESTest/scaffolding names and generated bytes are retained. The E-only copied workspaces do not alter archived GPT observations or shared dependencies. Process-build, Surefire failures/skips, report presence and mutant counts are reported alongside the unchanged scoring rule. This is configuration/runtime sensitivity, not an assertion-only causal ablation, a repeated-run variance estimate or a replacement 300-class baseline.'
NEW='The supplementary EvoSuite configuration (E1) enables assertions with MUTATION strategy, scaffolding and runtime dependency, retaining BRANCH, the 60-second budget, disabled test archive/separate classloader, and seeds 20261023 plus the original sampling-manifest 1-based index. Serial generation has a 240-second cap and at most one conditional sanitized-classpath retry; Maven measurement has a 300-second cap. Frozen native ESTest/scaffold sources are measured on all 49 keys under one E-only policy: upgrade a direct test-scope JUnit4 dependency to 4.13.2 only when its JAR lacks TestRule; override regular-tests includes only for inherited multiple executions with leading-slash patterns. Production and available selected-test bytecode, ordered classpaths and semantic POM changes are checked. Original clean/verify, JaCoCo/PIT goals, process gate and scoring remain unchanged; failures retain their slots. GPT observations and shared integration are untouched. Suite failures/skips and report/count evidence accompany scores. This configuration/runtime sensitivity neither isolates assertions nor estimates repeated-run variance or replaces the 300-class baseline.'
def sha(b):return hashlib.sha256(b).hexdigest()
before=P.read_bytes();assert sha(before)=='1a0259c630f8882dfa3b0c86052a74d9acc57ca05649215f6250ad26e0e0b55d'
assert before.count(OLD.encode())==1
after=before.replace(OLD.encode(),NEW.encode(),1)
assert after.replace(NEW.encode(),OLD.encode(),1)==before
backup=REV/'backups/method_policy_v1/03_method.tex';backup.parent.mkdir(parents=True,exist_ok=False)
with backup.open('xb') as f:f.write(before)
assert backup.read_bytes()==before
P.write_bytes(after)
assert P.read_bytes()==after
DIFF=REV/'backups/method_policy_v1/method_policy.diff'
with DIFF.open('x',encoding='utf-8',newline='') as f:f.write(''.join(difflib.unified_diff(before.decode().splitlines(True),after.decode().splitlines(True),fromfile='before/03_method.tex',tofile='after/03_method.tex')))
record={'path':str(P.relative_to(BASE)),'before_sha256':sha(before),'after_sha256':sha(after),'backup':str(backup.relative_to(BASE)),'backup_sha256':sha(backup.read_bytes()),'diff':str(DIFF.relative_to(BASE)),'diff_sha256':sha(DIFF.read_bytes()),'reason':'Document final fixed49 E-only compatibility measurement policy; same generation options/goals/gate/scoring; no outcome edits or trial narrative','only_one_paragraph_changed':True,'old_words':len(OLD.split()),'new_words':len(NEW.split()),'script_sha256':sha(Path(__file__).read_bytes())}
MAN=REV/'backups/method_policy_v1/revision.json'
with MAN.open('x',encoding='utf-8') as f:json.dump(record,f,ensure_ascii=False,indent=2);f.write('\n')
audit.log('FILE_REVISION',**record)
print(json.dumps(record,ensure_ascii=False,indent=2))
